import { expect, test } from '@playwright/test'
import { gridFits } from '../components/map3d/gridPlan'
import { GRID_SPEC_SAMPLES } from '../components/map3d/gridSpec.generated'

/**
 * The map's gridFits() must agree with the backend's tiles.plan() on every
 * sample box (generated by backend/maps/export_grid_spec.py), so it never
 * skips a box the backend accepts nor sends one it answers with 422.
 * Pure logic: no page.
 */
test('gridFits matches the backend tile plan on every sample', () => {
  expect(GRID_SPEC_SAMPLES.length).toBeGreaterThan(20)
  const wrong = GRID_SPEC_SAMPLES.filter(({ box, fits }) => {
    const [south, west, north, east] = box
    return gridFits({ south, west, north, east }) !== fits
  })
  expect(wrong).toEqual([])
})
